export const surahPagesMap: Record<number, number[]> = {};
export const pageSurahsMap: Record<number, number[]> = {};

for (let s = 1; s <= 114; s++) surahPagesMap[s] = [];
for (let p = 1; p <= 604; p++) pageSurahsMap[p] = [];

for (let p = 1; p <= 604; p++) {
  const list = quranPageMap[p] || [];
  list.forEach(entry => {
    if (!surahPagesMap[entry.surah].includes(p)) {
      surahPagesMap[entry.surah].push(p);
    }
    if (!pageSurahsMap[p].includes(entry.surah)) {
      pageSurahsMap[p].push(entry.surah);
    }
  });
}

export function getJuzPages(juz: number): number[] {
  let start = juz === 1 ? 1 : (juz === 30 ? 582 : (juz - 1) * 20 + 2);
  let len = juz === 1 ? 21 : (juz === 30 ? 23 : 20);
  let pages: number[] = [];
  for (let i = 0; i < len; i++) pages.push(start + i);
  return pages;
}

export const juzPagesMap: Record<number, number[]> = {};
export const juzSurahsMap: Record<number, number[]> = {};
export const juzShortSurahsMap: Record<number, number[]> = {};

for (let j = 1; j <= 30; j++) {
  const pList = getJuzPages(j);
  juzPagesMap[j] = pList;
  const sSet = new Set<number>();
  pList.forEach(p => {
    (pageSurahsMap[p] || []).forEach(s => sSet.add(s));
  });
  juzSurahsMap[j] = Array.from(sSet);
  // Short surahs: length <= 2 pages or all surahs in Juz 30
  juzShortSurahsMap[j] = Array.from(sSet).filter(s => j === 30 || surahPagesMap[s].length <= 2);
}

export function calculateSurahsAndAyahs(
  selectedPages: number[], 
  selectedSurahIds: number[], 
  history?: StudentQuranHistory | Set<number> | number[]
) {
  const activeSurahMap = new Map<number, { start: number; end: number; isExplicitFull: boolean }>();
  const explicitSurahs = new Set(selectedSurahIds);
  
  selectedSurahIds.forEach(sId => {
    activeSurahMap.set(sId, {
      start: 1,
      end: surahAyahCounts[sId],
      isExplicitFull: true
    });
  });
  
  const hasHistory = history && typeof history === 'object' && 'allFullSurahs' in history;

  selectedPages.forEach(p => {
    const pEntries = quranPageMap[p] || [];
    
    // إذا كانت هناك سور مكتملة سابقاً على هذه الصفحة ولكن هناك سورة غير مكتملة،
    // نعتمد فقط السور غير المكتملة أو السور المحددة صراحة
    let entriesToProcess = pEntries;
    if (hasHistory) {
      const fullSurahsSet = (history as StudentQuranHistory).allFullSurahs;
      const hasUnfinishedSurah = pEntries.some(e => !fullSurahsSet.has(e.surah) || explicitSurahs.has(e.surah));
      if (hasUnfinishedSurah) {
        entriesToProcess = pEntries.filter(e => explicitSurahs.has(e.surah) || !fullSurahsSet.has(e.surah));
      }
    }

    entriesToProcess.forEach(entry => {
      if (activeSurahMap.has(entry.surah)) {
        const cur = activeSurahMap.get(entry.surah)!;
        if (!cur.isExplicitFull) {
          cur.start = Math.min(cur.start, entry.start);
          cur.end = Math.max(cur.end, entry.end);
        }
      } else {
        activeSurahMap.set(entry.surah, {
          start: entry.start,
          end: entry.end,
          isExplicitFull: false
        });
      }
    });
  });
  
  const sortedSurahIds = Array.from(activeSurahMap.keys()).sort((a, b) => a - b);
  const surahNamesList = sortedSurahIds.map(sId => surahNames[sId]);
  
  const ayahParts: string[] = [];
  sortedSurahIds.forEach(sId => {
    const info = activeSurahMap.get(sId)!;
    const total = surahAyahCounts[sId];
    if (info.start === 1 && info.end === total) {
      // Full surah
    } else {
      ayahParts.push(info.start === info.end ? `${info.start}` : `${info.start}-${info.end}`);
    }
  });
  
  return {
    surahs: surahNamesList,
    ayahRange: ayahParts.join("، "),
    sortedSurahIds
  };
}

import type { Student, Evaluation } from '../types';

export function toEnglishDigits(val: string | number | undefined | null): string {
  if (val === undefined || val === null) return '';
  return String(val).replace(/[٠-٩]/g, (d) => (d.charCodeAt(0) - 1632).toString());
}

export const surahJuzMap: Record<number, number[]> = {};
for (let sId = 1; sId <= 114; sId++) {
  const pList = surahPagesMap[sId] || [];
  const jSet = new Set<number>();
  pList.forEach(p => {
    for (let j = 1; j <= 30; j++) {
      if (juzPagesMap[j]?.includes(p)) {
        jSet.add(j);
        break;
      }
    }
  });
  surahJuzMap[sId] = Array.from(jSet).sort((a, b) => a - b);
}

export interface StudentQuranHistory {
  allCountedPages: Set<number>;
  fullPages: Set<number>;
  partialPages: Set<number>;
  prevWeekFullPages: Set<number>;
  prevWeekPartialPages: Set<number>;
  priorFullPages: Set<number>;
  priorPartialPages: Set<number>;
  prevWeekFullSurahs: Set<number>;
  priorFullSurahs: Set<number>;
  allFullSurahs: Set<number>;
  allFullJuzs: Set<number>;
  prevWeekFullJuzs: Set<number>;
  priorFullJuzs: Set<number>;
  oldFullPages: Set<number>;
  newEvalsFullPages: Set<number>;
  oldFullSurahs: Set<number>;
  newEvalsFullSurahs: Set<number>;
  oldFullJuzs: Set<number>;
  newEvalsFullJuzs: Set<number>;
}

export function analyzeStudentQuranHistory(
  student: Student | null | undefined,
  evaluations: Evaluation[] = [],
  currentWeek: number = 1,
  currentEvalId?: number
): StudentQuranHistory {
  const allCountedPages = new Set<number>();
  const fullPages = new Set<number>();
  const partialPages = new Set<number>();
  const prevWeekFullPages = new Set<number>();
  const prevWeekPartialPages = new Set<number>();
  const priorFullPages = new Set<number>();
  const priorPartialPages = new Set<number>();
  const prevWeekFullSurahs = new Set<number>();
  const priorFullSurahs = new Set<number>();
  const allFullSurahs = new Set<number>();
  const allFullJuzs = new Set<number>();
  const prevWeekFullJuzs = new Set<number>();
  const priorFullJuzs = new Set<number>();
  const oldFullPages = new Set<number>();
  const newEvalsFullPages = new Set<number>();
  const oldFullSurahs = new Set<number>();
  const newEvalsFullSurahs = new Set<number>();
  const oldFullJuzs = new Set<number>();
  const newEvalsFullJuzs = new Set<number>();

  if (!student) {
    return {
      allCountedPages,
      fullPages,
      partialPages,
      prevWeekFullPages,
      prevWeekPartialPages,
      priorFullPages,
      priorPartialPages,
      prevWeekFullSurahs,
      priorFullSurahs,
      allFullSurahs,
      allFullJuzs,
      prevWeekFullJuzs,
      priorFullJuzs,
      oldFullPages,
      newEvalsFullPages,
      oldFullSurahs,
      newEvalsFullSurahs,
      oldFullJuzs,
      newEvalsFullJuzs,
    };
  }

  // 1. Parse oldMemorizedPages
  const oldPages = new Set<number>();
  if (student.oldMemorizedPages) {
    const cleaned = toEnglishDigits(student.oldMemorizedPages.replace(/[\u200E\u200F\u202A-\u202E]/g, ''));
    const parts = cleaned.split(/[,،]/);
    for (const part of parts) {
      const range = part.trim().split(/[-–—]/);
      if (range.length === 2) {
        const start = parseInt(range[0].trim(), 10);
        const end = parseInt(range[1].trim(), 10);
        if (!isNaN(start) && !isNaN(end)) {
          const s = Math.min(start, end);
          const e = Math.max(start, end);
          for (let i = s; i <= e; i++) {
            if (i >= 1 && i <= 604) oldPages.add(i);
          }
        }
      } else if (range.length === 1) {
        const num = parseInt(range[0].trim(), 10);
        if (!isNaN(num) && num >= 1 && num <= 604) oldPages.add(num);
      }
    }
  }

  oldPages.forEach(p => {
    allCountedPages.add(p);
    fullPages.add(p);
    priorFullPages.add(p);
  });

  const coveredSurahsByPage = new Map<number, Set<number>>();
  oldPages.forEach(p => {
    const surahsOnPage = pageSurahsMap[p] || [];
    coveredSurahsByPage.set(p, new Set(surahsOnPage));
  });

  // 2. Filter past evaluations
  const pastEvals = evaluations
    .filter(e => 
      e.studentId === student.id &&
      e.weekNumber < currentWeek &&
      (!currentEvalId || e.id !== currentEvalId) &&
      e.subject !== 'mutoon' &&
      e.newMemorizedPages &&
      e.newMemorizedPages.length > 0
    )
    .sort((a, b) => a.weekNumber - b.weekNumber);

  const lastPastEval = pastEvals.length > 0 ? pastEvals[pastEvals.length - 1] : null;
  const lastEvalWeekNumber = lastPastEval ? lastPastEval.weekNumber : -1;

  const pageLastTouchWeek = new Map<number, number>();
  const surahLastTouchWeek = new Map<number, number>();

  pastEvals.forEach(e => {
    const evalSurahNames = e.surahs || [];
    const evalSurahIds = new Set<number>();
    evalSurahNames.forEach(name => {
      const id = surahNames.indexOf(name);
      if (id > 0) evalSurahIds.add(id);
    });

    const isExplicitSurahEval = evalSurahIds.size > 0;

    e.newMemorizedPages?.forEach(p => {
      if (p < 1 || p > 604) return;
      allCountedPages.add(p);
      pageLastTouchWeek.set(p, e.weekNumber);

      if (!coveredSurahsByPage.has(p)) {
        coveredSurahsByPage.set(p, new Set());
      }
      const pageCoveredSet = coveredSurahsByPage.get(p)!;

      if (isExplicitSurahEval) {
        const surahsOnPage = pageSurahsMap[p] || [];
        surahsOnPage.forEach(sId => {
          if (evalSurahIds.has(sId)) {
            pageCoveredSet.add(sId);
          }
        });
      } else {
        const surahsOnPage = pageSurahsMap[p] || [];
        surahsOnPage.forEach(sId => pageCoveredSet.add(sId));
      }
    });

    evalSurahIds.forEach(sId => {
      surahLastTouchWeek.set(sId, e.weekNumber);
    });
  });

  // 3. Classify all pages
  for (let p = 1; p <= 604; p++) {
    const pageCoveredSet = coveredSurahsByPage.get(p);
    if (!pageCoveredSet || pageCoveredSet.size === 0) continue;

    const surahsOnPage = pageSurahsMap[p] || [];
    const isAllSurahsCovered = surahsOnPage.every(sId => pageCoveredSet.has(sId));
    const touchWeek = pageLastTouchWeek.get(p) || 0;
    const isFromLastEval = touchWeek === lastEvalWeekNumber && lastEvalWeekNumber > 0 && !oldPages.has(p);

    if (isAllSurahsCovered || oldPages.has(p)) {
      fullPages.add(p);
      if (oldPages.has(p)) {
        oldFullPages.add(p);
      } else {
        newEvalsFullPages.add(p);
      }

      if (isFromLastEval) {
        prevWeekFullPages.add(p);
      } else {
        priorFullPages.add(p);
      }
    } else {
      // Partial page (منقطة الإطار)
      partialPages.add(p);
      if (isFromLastEval) {
        prevWeekPartialPages.add(p);
      } else {
        priorPartialPages.add(p);
      }
    }
  }

  // 4. Classify all Surahs (Surahs are only full, never dotted!)
  for (let sId = 1; sId <= 114; sId++) {
    const sPages = surahPagesMap[sId] || [];
    if (sPages.length === 0) continue;

    const isSurahComplete = sPages.every(p => {
      const pageCoveredSet = coveredSurahsByPage.get(p);
      return pageCoveredSet && pageCoveredSet.has(sId);
    });

    if (isSurahComplete) {
      allFullSurahs.add(sId);
      const isAllInOldPages = sPages.every(p => oldPages.has(p));
      if (isAllInOldPages) {
        oldFullSurahs.add(sId);
      } else {
        newEvalsFullSurahs.add(sId);
      }

      const touchWeek = surahLastTouchWeek.get(sId) || 0;
      const allPrevWeek = sPages.every(p => prevWeekFullPages.has(p));
      if (touchWeek === lastEvalWeekNumber || allPrevWeek) {
        prevWeekFullSurahs.add(sId);
      } else {
        priorFullSurahs.add(sId);
      }
    }
  }

  // 5. Classify all Juzs
  for (let j = 1; j <= 30; j++) {
    const jPages = juzPagesMap[j] || [];
    const isJuzComplete = jPages.length > 0 && jPages.every(p => fullPages.has(p));
    if (isJuzComplete) {
      allFullJuzs.add(j);
      const isAllInOldPages = jPages.every(p => oldPages.has(p));
      if (isAllInOldPages) {
        oldFullJuzs.add(j);
      } else {
        newEvalsFullJuzs.add(j);
      }

      const isPrevWeek = jPages.every(p => prevWeekFullPages.has(p));
      if (isPrevWeek) {
        prevWeekFullJuzs.add(j);
      } else {
        priorFullJuzs.add(j);
      }
    }
  }

  return {
    allCountedPages,
    fullPages,
    partialPages,
    prevWeekFullPages,
    prevWeekPartialPages,
    priorFullPages,
    priorPartialPages,
    prevWeekFullSurahs,
    priorFullSurahs,
    allFullSurahs,
    allFullJuzs,
    prevWeekFullJuzs,
    priorFullJuzs,
    oldFullPages,
    newEvalsFullPages,
    oldFullSurahs,
    newEvalsFullSurahs,
    oldFullJuzs,
    newEvalsFullJuzs,
  };
}

export function computeSelectionState(
  selectedPages: number[], 
  selectedSurahIds: number[], 
  history?: StudentQuranHistory | Set<number> | number[]
) {
  const allCountedPages = history instanceof Set 
    ? history 
    : Array.isArray(history) 
      ? new Set(history) 
      : history?.allCountedPages || new Set<number>();

  const directSurahs = new Set<number>(selectedSurahIds);
  const derivedSurahs = new Set<number>();
  
  const hasHistory = history && typeof history === 'object' && 'allFullSurahs' in history;
  const allFullSurahs = hasHistory ? (history as StudentQuranHistory).allFullSurahs : new Set<number>();

  // السور المشتقة من تحديد أرقام الصفحات
  selectedPages.forEach(p => {
    const sList = pageSurahsMap[p] || [];
    const uncompletedSurahsOnPage = sList.filter(s => !allFullSurahs.has(s) || directSurahs.has(s));
    const targetSurahs = (hasHistory && uncompletedSurahsOnPage.length > 0) ? uncompletedSurahsOnPage : sList;
    targetSurahs.forEach(s => {
      if (!directSurahs.has(s)) {
        derivedSurahs.add(s);
      }
    });
  });

  const directPages = new Set<number>(selectedPages);
  const derivedPages = new Set<number>();
  
  // الصفحات المشتقة من تحديد السور
  selectedSurahIds.forEach(s => {
    const pList = surahPagesMap[s] || [];
    pList.forEach(p => {
      if (!directPages.has(p)) {
        derivedPages.add(p);
      }
    });
  });

  const allActivePages = Array.from(new Set([...selectedPages, ...Array.from(derivedPages)])).sort((a, b) => a - b);

  // الصفحات الجديدة المحسوبة فعلياً في الحفظ الجديد (باستثناء الصفحات المحسوبة سابقاً)
  const newlyCountedPages = allActivePages.filter(p => !allCountedPages.has(p));
  const newPagesCount = newlyCountedPages.length;

  // الصفحات المحسوبة سابقاً والتي يتم إكمالها في هذا التحديد
  const recompletedPages = allActivePages.filter(p => allCountedPages.has(p));
  const recompletedPagesCount = recompletedPages.length;

  return {
    directSurahs,
    derivedSurahs,
    directPages,
    derivedPages,
    allActivePages,
    newlyCountedPages,
    newPagesCount,
    recompletedPages,
    recompletedPagesCount,
    fullSurahs: directSurahs,
    partialSurahs: derivedSurahs,
    fullPages: directPages,
    partialPages: derivedPages
  };
}
